def.template:
{
  "messages": [
    {"sender":"alerts@yahoo.com","subject":"Security notice","date":"2025-11-20","size":"12 KB","unread":true},
    {"sender":"news@yahoofinance.com","subject":"Market wrap","date":"2025-11-19","size":"34 KB","unread":false},
    {"sender":"friend@example.com","subject":"Weekend plans","date":"2025-11-18","size":"8 KB","unread":true}
  ]
}

xquery.xq-expression:
declare variable $mailbox as node() external;
declare variable $onlyUnread as xs:boolean external;
<messages>{
    for $m in $mailbox//messages
    let $isUnread := ($m/unread = "true")
    return
        if ($onlyUnread and not($isUnread)) then ()
        else
            <mail unread="{$isUnread}">
                <sender>{data($m/sender)}</sender>
                <subject>{data($m/subject)}</subject>
                <date>{data($m/date)}</date>
                <size>{data($m/size)}</size>
            </mail>
}</messages>
